/**
 * Pure helpers for the Binance Spot symbol directory (the set of currently
 * tradable symbols from `GET /api/v3/exchangeInfo`): parsing the REST
 * response, and turning loose user input ("btc", "eth/usdt") into a real
 * symbol. No network or DOM, so it can be unit tested in isolation.
 */

/** Quote assets tried, in order, when the user types a bare base asset such as "BTC". */
export const SHORTHAND_QUOTE_ASSETS = ['USDT', 'USDC', 'FDUSD', 'BTC'] as const;

interface RawExchangeInfoSymbol {
  symbol?: unknown;
  status?: unknown;
  isSpotTradingAllowed?: unknown;
}

/** Extracts the sorted list of spot-tradable symbols from an `exchangeInfo` response; `[]` for anything malformed. */
export function parseExchangeInfoSymbols(raw: unknown): string[] {
  const list = typeof raw === 'object' && raw !== null ? (raw as { symbols?: unknown }).symbols : undefined;
  if (!Array.isArray(list)) return [];
  const out: string[] = [];
  for (const entry of list as RawExchangeInfoSymbol[]) {
    if (typeof entry !== 'object' || entry === null || typeof entry.symbol !== 'string') continue;
    if (entry.status !== undefined && entry.status !== 'TRADING') continue;
    if (entry.isSpotTradingAllowed === false) continue;
    out.push(entry.symbol.toUpperCase());
  }
  return out.sort();
}

/** Uppercases and strips whitespace and common pair separators ("eth/usdt", "btc-usdt"). Non-ASCII symbols are left intact. */
export function normalizeSymbolInput(input: string): string {
  return input.toUpperCase().replace(/[\s/\-_:]+/g, '');
}

/**
 * Resolves loose input to a symbol: an exact match first, then
 * `<input><quote>` for each of `SHORTHAND_QUOTE_ASSETS`. Returns `null` for
 * empty or unknown input. When `known` is `null` (directory not loaded yet,
 * or unreachable) any non-empty input is accepted as typed, so symbol entry
 * never hard-depends on the directory request succeeding.
 */
export function resolveSymbol(input: string, known: ReadonlySet<string> | null): string | null {
  const normalized = normalizeSymbolInput(input);
  if (!normalized) return null;
  if (!known || known.has(normalized)) return normalized;
  for (const quote of SHORTHAND_QUOTE_ASSETS) {
    const candidate = normalized + quote;
    if (known.has(candidate)) return candidate;
  }
  return null;
}

import { describe, it, expect } from 'vitest';
import { normalizeSymbolInput, parseExchangeInfoSymbols, resolveSymbol } from './symbols';

const KNOWN = new Set(['BTCUSDT', 'ETHUSDT', 'ETHBTC', 'SOLUSDC', 'WBTCBTC']);

describe('parseExchangeInfoSymbols', () => {
  it('keeps only TRADING, spot-allowed symbols, sorted', () => {
    const list = parseExchangeInfoSymbols({
      symbols: [
        { symbol: 'ETHUSDT', status: 'TRADING', isSpotTradingAllowed: true },
        { symbol: 'BTCUSDT', status: 'TRADING', isSpotTradingAllowed: true },
        { symbol: 'LUNAUSDT', status: 'BREAK', isSpotTradingAllowed: true },
        { symbol: 'MARGINONLY', status: 'TRADING', isSpotTradingAllowed: false },
      ],
    });
    expect(list).toEqual(['BTCUSDT', 'ETHUSDT']);
  });

  it('returns [] for malformed payloads and skips malformed entries', () => {
    expect(parseExchangeInfoSymbols(null)).toEqual([]);
    expect(parseExchangeInfoSymbols({ symbols: 'nope' })).toEqual([]);
    expect(parseExchangeInfoSymbols({ symbols: [null, { symbol: 42 }, { symbol: 'BTCUSDT' }] })).toEqual(['BTCUSDT']);
  });
});

describe('normalizeSymbolInput', () => {
  it('uppercases and strips whitespace and pair separators', () => {
    expect(normalizeSymbolInput(' eth/usdt ')).toBe('ETHUSDT');
    expect(normalizeSymbolInput('btc-usdt')).toBe('BTCUSDT');
    expect(normalizeSymbolInput('sol_usdc')).toBe('SOLUSDC');
  });

  it('leaves non-ASCII symbol characters intact', () => {
    expect(normalizeSymbolInput('币安人生usdt')).toBe('币安人生USDT');
  });
});

describe('resolveSymbol', () => {
  it('accepts exact matches regardless of case or separators', () => {
    expect(resolveSymbol('ethbtc', KNOWN)).toBe('ETHBTC');
    expect(resolveSymbol('ETH/BTC', KNOWN)).toBe('ETHBTC');
  });

  it('expands a bare base asset using the first quote asset that exists', () => {
    expect(resolveSymbol('btc', KNOWN)).toBe('BTCUSDT');
    expect(resolveSymbol('sol', KNOWN)).toBe('SOLUSDC');
    expect(resolveSymbol('wbtc', KNOWN)).toBe('WBTCBTC');
  });

  it('rejects unknown and empty input', () => {
    expect(resolveSymbol('NOTACOIN', KNOWN)).toBeNull();
    expect(resolveSymbol('   ', KNOWN)).toBeNull();
  });

  it('accepts any non-empty input as typed when the directory is unavailable', () => {
    expect(resolveSymbol('btc', null)).toBe('BTC');
    expect(resolveSymbol('', null)).toBeNull();
  });
});

import { useSyncExternalStore } from 'react';
import { REST_HOSTS } from '../core/hub/hosts';
import { parseExchangeInfoSymbols } from '../core/symbols/symbols';

/**
 * Per-window directory of tradable Binance Spot symbols, backing symbol-input
 * autocomplete and validation. It's a one-off REST request rather than
 * streaming data, so it's fetched on the main thread instead of through the
 * SharedWorker hub, and cached in localStorage for a day so reloads and
 * pop-outs don't refetch it.
 */

const CACHE_KEY = 'trading-workstation:symbols';
const CACHE_TTL_MS = 24 * 3600 * 1000;
const RETRY_AFTER_MS = 60_000;
const EXCHANGE_INFO_PATH = '/api/v3/exchangeInfo?symbolStatus=TRADING';

/** `id` of the single shared `<datalist>` (see `SymbolDatalist`) that every symbol input points its `list` attribute at. */
export const SYMBOL_DATALIST_ID = 'tw-symbol-options';

let symbolSet: ReadonlySet<string> | null = null;
let sortedSymbols: readonly string[] = [];
let requested = false;
const listeners = new Set<() => void>();

function publish(list: string[]): void {
  sortedSymbols = list;
  symbolSet = new Set(list);
  for (const listener of listeners) listener();
}

function readCache(): string[] | null {
  try {
    const raw = localStorage.getItem(CACHE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as { fetchedAt?: unknown; symbols?: unknown };
    if (typeof parsed.fetchedAt !== 'number' || Date.now() - parsed.fetchedAt > CACHE_TTL_MS) return null;
    if (!Array.isArray(parsed.symbols) || parsed.symbols.length === 0) return null;
    if (!parsed.symbols.every((s) => typeof s === 'string')) return null;
    return parsed.symbols as string[];
  } catch {
    return null;
  }
}

function writeCache(list: string[]): void {
  try {
    localStorage.setItem(CACHE_KEY, JSON.stringify({ fetchedAt: Date.now(), symbols: list }));
  } catch {
    // Storage unavailable or full - we'll just refetch next time.
  }
}

async function fetchSymbols(): Promise<string[]> {
  for (const base of [REST_HOSTS.primary, REST_HOSTS.fallback]) {
    try {
      const res = await fetch(base + EXCHANGE_INFO_PATH);
      if (!res.ok) continue;
      const list = parseExchangeInfoSymbols(await res.json());
      if (list.length > 0) return list;
    } catch {
      // Network/CORS failure on this host - try the next one.
    }
  }
  return [];
}

function ensureLoaded(): void {
  if (requested) return;
  requested = true;
  const cached = readCache();
  if (cached) {
    publish(cached);
    return;
  }
  void fetchSymbols().then((list) => {
    if (list.length === 0) {
      console.warn('[symbolDirectory] could not load the Binance symbol list; symbol inputs will accept any value.');
      setTimeout(() => {
        requested = false;
        if (listeners.size > 0) ensureLoaded();
      }, RETRY_AFTER_MS);
      return;
    }
    writeCache(list);
    publish(list);
  });
}

function subscribe(listener: () => void): () => void {
  ensureLoaded();
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** Set of known symbols, or `null` until the directory has loaded (callers should then accept input as typed). */
export function useSymbolSet(): ReadonlySet<string> | null {
  return useSyncExternalStore(subscribe, () => symbolSet);
}

/** Alphabetical list of known symbols; empty until loaded. */
export function useSortedSymbols(): readonly string[] {
  return useSyncExternalStore(subscribe, () => sortedSymbols);
}

import { SYMBOL_DATALIST_ID, useSortedSymbols } from './symbolDirectory';

/**
 * Rendered once per window. Every symbol input references it via
 * `list={SYMBOL_DATALIST_ID}` rather than owning a copy, so 30 panels don't
 * mean 30 × ~1500 `<option>` nodes.
 */
export function SymbolDatalist() {
  const symbols = useSortedSymbols();
  return (
    <datalist id={SYMBOL_DATALIST_ID}>
      {symbols.map((s) => (
        <option key={s} value={s} />
      ))}
    </datalist>
  );
}

